function wordCount(text) {
  const matches = String(text).toLowerCase().match(/[a-z]+/g) || [];
  const counts = {};

  for (const word of matches) {
    if (Object.prototype.hasOwnProperty.call(counts, word)) {
      counts[word] += 1;
    } else {
      counts[word] = 1;
    }
  }

  return counts;
}
