```javascript
function fib(n) {
  if (!Number.isInteger(n) || n < 0) return NaN;
  let a = 0, b = 1;
  for (let i = 0; i < n; i++) {
    const next = a + b;
    a = b;
    b = next;
  }
  return a;
}
