```javascript
function chunk(array, size) {
  if (!Array.isArray(array)) return [];
  const n = Math.floor(Number(size));
  if (!Number.isFinite(n) || n <= 0) return [];
  const result = [];
  for (let i = 0; i < array.length; i += n) {
    result.push(array.slice(i, i + n));
  }
  return result;
}
